package com.aivle.backend.journey.conceptcore;
import com.aivle.backend.common.entity.BaseEntity;import com.aivle.backend.project.entity.Project;import jakarta.persistence.*;import lombok.AccessLevel;import lombok.Getter;import lombok.NoArgsConstructor;
@Entity @Table(name="exploration_concepts") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class ExplorationConcept extends BaseEntity {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="project_id",nullable=false) private Project project;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="batch_id",nullable=false) private ConceptExplorationBatch batch;@OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="slot_id",nullable=false) private ConceptSlot slot;@OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="concept_attempt_id",nullable=false) private ConceptAttempt attempt;@Column(nullable=false) private int displayOrder;@Column(nullable=false,length=200) private String conceptName;@Column(nullable=false,columnDefinition="TEXT") private String skeletonJson;@Enumerated(EnumType.STRING) @Column(nullable=false,length=40) private ConceptSlot.LegalState legalState;@Column(nullable=false) private int assessmentVersion;@Column(nullable=false,length=71) private String validatedSnapshotHash;public static ExplorationConcept create(ConceptExplorationBatch batch,ConceptSlot slot,ConceptAttempt attempt,int order,String name,String skeleton,ConceptSlot.LegalState legal,String hash){if(!slot.isEligible())throw new IllegalArgumentException("only eligible slot is public");ExplorationConcept v=new ExplorationConcept();v.project=batch.getProject();v.batch=batch;v.slot=slot;v.attempt=attempt;v.displayOrder=order;v.conceptName=name;v.skeletonJson=skeleton;v.legalState=legal;v.assessmentVersion=1;v.validatedSnapshotHash=hash;return v;}}
